const details = [];
function P(id, name, kind, city, state, date, summary, why_go, best_for, secondary_for, categories, duration_minutes, source_ids, options = {}) {
  details.push({
    id, name, kind, city, state, visit_date: date, summary, why_go, best_for, secondary_for,
    best_fit_note: options.best_fit_note || `Best fit for ${best_for.join(" and ")}: ${why_go}`,
    categories, duration_minutes, source_ids, reservation: options.reservation || "none",
    hours: options.hours || { opens: null, closes: null, status: "public-space-or-confirm", note: "Confirm interior access close to travel." },
    cost: options.cost || { amount_per_person: 0, status: "free", note: "No admission planned." },
    priority: options.priority || "anchor", replacement_reason: options.replacement_reason
  });
}
